// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNum, uint256 value) public {
        value = bound(value, 10 ether, 10 ether);
        timestamp = bound(timestamp, 1, type(uint256).max);
        blockNum = bound(blockNum, 15, type(uint256).max);
        blockNum = blockNum - (blockNum % 15);

        address caller = address(0x123456);
        vm.deal(caller, value);
        vm.warp(timestamp);
        vm.roll(blockNum);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: value}("");
        require(ok, "call failed");

        assertTrue(address(c).balance == 0);
    }
}
